mapper.select:
SELECT distinct A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, CONCAT_WS( '', A.FINPROD_ID, ',', B.IS_CYCLE, ',', B.DEAL_MODE, ',', C.CASH_ID, ',', A.PROFIT_TYPE, ',', DATE_FORMAT(A.VDATE,'%Y-%m-%d'), ',', (CASE WHEN D.OPEN_TYPE = #{openType03} THEN #{openType03} ELSE #{openType01} END) , ',' , DATE_FORMAT(A.MDATE,'%Y-%m-%d') ) object FROM FIN_PRODUCT A INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID, FIN_PRODUCT_ADD B, FIN_CASH_INFO C, FIN_OPEN_RULE D
WHERE A.FINPROD_ID = B.FINPROD_ID AND A.OPERATION_TYPE = #{ISSUE_MODE_01,jdbcType=VARCHAR} AND A.FINPROD_ID = C.FINPROD_ID AND C.CASH_ID = D.CASH_ID AND D.OPEN_MODE != #{OPENMODE_02,jdbcType=VARCHAR}
AND (A.FINPROD_MARKET_ID LIKE CONCAT('%',#{search,jdbcType=VARCHAR},'%') or A.FINPROD_ABBR LIKE CONCAT('%',#{search,jdbcType=VARCHAR},'%') )
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName}

SELECT FIN_OPEN_PLAN.CASH_ID cashId, FIN_OPEN_PLAN.OPEN_TYPE openType, OPEN_DATE_STR openDateStr, FIN_OPEN_PLAN.OPEN_DATE_END openDateEnd, OPEN_VDATE openVdate, OPEN_NDATE openNdate, OPEN_DATE_STR_UN openDateStrUn, OPEN_DATE_END_UN openDateEndUn, OPEN_VDATE_UN openVdateUn, OPEN_MDATE_UN openMdateUn, FIN_OPEN_PLAN.FINPROD_ID finprodId, BRANCH branch, OPEN_STATUS openStatus, SI.SEND_STATUS sendStatus, SI.SEND_REMARK sendRemark FROM FIN_OPEN_PLAN INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_OPEN_PLAN.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName} LEFT JOIN INF_FIN_OPEN_PLAN SI ON FIN_OPEN_PLAN.CASH_ID = SI.CASH_ID AND FIN_OPEN_PLAN.OPEN_TYPE = SI.OPEN_TYPE AND FIN_OPEN_PLAN.OPEN_DATE_END = SI.OPEN_DATE_END WHERE FIN_OPEN_PLAN.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and FIN_OPEN_PLAN.OPEN_TYPE = if(FIN_OPEN_PLAN.OPEN_TYPE= #{openType03}, #{openType03}, #{scheduletype})
AND IFNULL(SI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
ORDER BY OPEN_DATE_STR ASC

SELECT DISTINCT FIN_PRODUCT.FINPROD_ID id, CONCAT_WS('',FIN_PRODUCT.FINPROD_MARKET_ID ,':', FIN_PRODUCT.FINPROD_ABBR) text, CONCAT_WS('',FIN_PRODUCT.FINPROD_MARKET_ID , ',' , FIN_PRODUCT_ADD.DEAL_MODE) object, FIN_PRODUCT.VDATE col FROM FIN_PRODUCT, PTL_MANAGE_OBJ, PTL_PORTFOLIO_AUTHORITY, FIN_PRODUCT_ADD
FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} AND PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID AND PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_PRODUCT.OPERATION_TYPE = #{operationType}
AND (FIN_PRODUCT.FINPROD_ID like concat('%',#{search,jdbcType=VARCHAR},'%') OR FIN_PRODUCT.FINPROD_ABBR like concat('%',#{search,jdbcType=VARCHAR},'%') )
